C++<pre><code>#include &lt;jetbot/motor_controller.hpp&gt;
#include &lt;thread&gt;
#include &lt;mutex&gt;

int main() {
    jetbot::MotorController motor;
    std::mutex motor_mutex;

    // Control thread
    std::thread control_thread([&amp;]() {
        while (true) {
            {
                std::lock_guard&lt;std::mutex&gt; lock(motor_mutex);
                motor.setVelocity(0.5, 0.0);
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    });

    // Monitoring thread
    std::thread monitor_thread([&amp;]() {
        while (true) {
            {
                std::lock_guard&lt;std::mutex&gt; lock(motor_mutex);
                auto state = motor.getMotorState();
                std::cout &lt;&lt; "Velocity: " &lt;&lt; state.left_velocity &lt;&lt; std::endl;
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(500));
        }
    });

    // Wait for threads
    control_thread.join();
    monitor_thread.join();

    return 0;
}
