C++<pre><code>#include "jetbot_detection/object_detector.hpp"

namespace jetbot_detection
{

ObjectDetector::ObjectDetector(const rclcpp::NodeOptions &amp; options)
: Node("object_detector", options)
{
  // Declare parameters
  this-&gt;declare_parameter&lt;std::string&gt;("model_path", "/models/yolov8n.engine");
  this-&gt;declare_parameter&lt;double&gt;("confidence_threshold", 0.5);

  // Get parameters
  model_path_ = this-&gt;get_parameter("model_path").as_string();
  confidence_threshold_ = this-&gt;get_parameter("confidence_threshold").as_double();

  // Create subscriber
  image_sub_ = this-&gt;create_subscription&lt;sensor_msgs::msg::Image&gt;(
    "/camera/image_raw",
    10,
    std::bind(&amp;ObjectDetector::imageCallback, this, std::placeholders::_1));

  // Create publisher
  detection_pub_ = this-&gt;create_publisher&lt;vision_msgs::msg::Detection2DArray&gt;(
    "/detections",
    10);

  // Initialize engine
  if (!initializeEngine()) {
    RCLCPP_ERROR(this-&gt;get_logger(), "Failed to initialize TensorRT engine");
    throw std::runtime_error("Engine initialization failed");
  }

  RCLCPP_INFO(this-&gt;get_logger(), "Object detector initialized");
}

void ObjectDetector::imageCallback(const sensor_msgs::msg::Image::SharedPtr msg)
{
  RCLCPP_DEBUG(this-&gt;get_logger(), "Received image: %dx%d", msg-&gt;width, msg-&gt;height);

  // Process image
  auto detections = std::make_shared&lt;vision_msgs::msg::Detection2DArray&gt;();
  // ... processing logic

  detection_pub_-&gt;publish(*detections);
}

}  // namespace jetbot_detection

