C++<pre><code>// tests/cpp/test_slam_node.cpp
#include &lt;gtest/gtest.h&gt;
#include &lt;rclcpp/rclcpp.hpp&gt;
#include "jetbot_slam/slam_node.hpp"

class SlamNodeTest : public ::testing::Test {
protected:
    void SetUp() override {
        rclcpp::init(0, nullptr);
        node_ = std::make_shared&lt;jetbot_slam::SlamNode&gt;();
    }

    void TearDown() override {
        node_.reset();
        rclcpp::shutdown();
    }

    std::shared_ptr&lt;jetbot_slam::SlamNode&gt; node_;
};

TEST_F(SlamNodeTest, Initialization) {
    EXPECT_NE(node_, nullptr);
    EXPECT_STREQ(node_-&gt;get_name(), "slam_node");
}

TEST_F(SlamNodeTest, MapCreation) {
    // Create test scan
    auto scan = std::make_shared&lt;sensor_msgs::msg::LaserScan&gt;();
    scan-&gt;ranges.resize(360, 1.0);

    node_-&gt;processScan(scan);

    auto map = node_-&gt;getMap();
    EXPECT_GT(map.info.width, 0);
    EXPECT_GT(map.info.height, 0);
}

TEST_F(SlamNodeTest, LoopClosureDetection) {
    // Test loop closure
    EXPECT_TRUE(node_-&gt;enableLoopClosure(true));

    // Simulate repeated scans at same location
    auto scan = createTestScan();
    for (int i = 0; i &lt; 10; ++i) {
        node_-&gt;processScan(scan);
    }

    EXPECT_TRUE(node_-&gt;hasDetectedLoopClosure());
