C++<pre><code>#include &lt;jetbot_cuda_vision/video_processor.hpp&gt;
#include &lt;opencv2/opencv.hpp&gt;
#include &lt;iostream&gt;

int main() {
    const int WIDTH = 1280;
    const int HEIGHT = 720;
    const int FPS = 30;

    // Open video source
    cv::VideoCapture cap(0);
    cap.set(cv::CAP_PROP_FRAME_WIDTH, WIDTH);
    cap.set(cv::CAP_PROP_FRAME_HEIGHT, HEIGHT);
    cap.set(cv::CAP_PROP_FPS, FPS);

    if (!cap.isOpened()) {
        std::cerr &lt;&lt; "Failed to open camera\n";
        return 1;
    }

    // Create video processor
    jetbot::VideoProcessor video_proc(WIDTH, HEIGHT, FPS, 10);

    // Define processing chain
    std::vector&lt;jetbot::ProcessingOp&gt; chain = {
        {jetbot::OpType::GRAYSCALE, {}},
        {jetbot::OpType::GAUSSIAN_BLUR, {{"kernel_size", 5}, {"sigma", 1.5}}},
        {jetbot::OpType::CANNY_EDGE, {{"low_threshold", 50}, {"high_threshold", 150}}}
    };
    video_proc.setProcessingChain(chain);

    // Allocate GPU buffers
    size_t gpu_size = WIDTH * HEIGHT * 4;
    uint8_t *input_gpu, *output_gpu;
    cudaMalloc(&amp;input_gpu, gpu_size);
    cudaMalloc(&amp;output_gpu, gpu_size);

    cv::Mat frame;
    int frame_count = 0;

    while (true) {
        // Capture frame
        cap &gt;&gt; frame;
        if (frame.empty()) break;

        // Convert BGR to RGBA
        cv::Mat rgba_frame;
        cv::cvtColor(frame, rgba_frame, cv::COLOR_BGR2RGBA);

        // Upload to GPU
        cudaMemcpy(input_gpu, rgba_frame.data, gpu_size, 
                   cudaMemcpyHostToDevice);

        // Process
        video_proc.enqueueFrame(input_gpu);

        if (video_proc.getProcessedFrame(output_gpu, 100)) {
            // Download result
            uint8_t *host_output = new uint8_t[gpu_size];
            cudaMemcpy(host_output, output_gpu, gpu_size, 
                       cudaMemcpyDeviceToHost);

            // Convert back to OpenCV format
            cv::Mat result(HEIGHT, WIDTH, CV_8UC4, host_output);

            // Display
            cv::imshow("CUDA Vision Stream", result);

            // Performance metrics
            frame_count++;
            if (frame_count % 30 == 0) {
                std::cout &lt;&lt; "Processed frames: " &lt;&lt; frame_count &lt;&lt; "\n";
            }

            delete[] host_output;
        }

        // Exit on 'q' key
        if (cv::waitKey(1) == 'q') break;
    }

    // Cleanup
    cudaFree(input_gpu);
    cudaFree(output_gpu);
    cap.release();
    cv::destroyAllWindows();

    std::cout &lt;&lt; "✅ Stream processing complete\n";
    return 0;
}
</code></pre>

C++<pre><code>#include &lt;jetbot_cuda_vision/feature_extraction.hpp&gt;
#include &lt;opencv2/opencv.hpp&gt;
#include &lt;iostream&gt;
#include &lt;vector&gt;

int main() {
    // Load images
    cv::Mat img1 = cv::imread("image1.jpg", cv::IMREAD_GRAYSCALE);
    cv::Mat img2 = cv::imread("image2.jpg", cv::IMREAD_GRAYSCALE);

    if (img1.empty() || img2.empty()) {
        std::cerr &lt;&lt; "Failed to load images\n";
        return 1;
    }

    int width = img1.cols;
    int height = img1.rows;

    // Allocate GPU memory
    uint8_t *gpu_img1, *gpu_img2;
    cudaMalloc(&amp;gpu_img1, width * height);
    cudaMalloc(&amp;gpu_img2, width * height);

    cudaMemcpy(gpu_img1, img1.data, width * height, 
               cudaMemcpyHostToDevice);
    cudaMemcpy(gpu_img2, img2.data, width * height, 
               cudaMemcpyHostToDevice);

    // Extract features
    std::vector&lt;jetbot::Keypoint&gt; kps1, kps2;
    std::vector&lt;jetbot::Descriptor&gt; descs1, descs2;

    std::cout &lt;&lt; "Extracting features from image 1...\n";
    jetbot::extractSIFTFeatures(gpu_img1, kps1, descs1, width, height, 0.03f);

    std::cout &lt;&lt; "Extracting features from image 2...\n";
    jetbot::extractSIFTFeatures(gpu_img2, kps2, descs2, width, height, 0.03f);

    std::cout &lt;&lt; "Image 1 keypoints: " &lt;&lt; kps1.size() &lt;&lt; "\n";
    std::cout &lt;&lt; "Image 2 keypoints: " &lt;&lt; kps2.size() &lt;&lt; "\n";

    // Simple feature matching (brute force)
    std::vector&lt;cv::DMatch&gt; matches;
    const float MATCH_THRESHOLD = 0.7f;

    for (size_t i = 0; i &lt; descs1.size(); i++) {
        float best_dist = std::numeric_limits&lt;float&gt;::max();
        float second_best_dist = std::numeric_limits&lt;float&gt;::max();
        int best_idx = -1;

        for (size_t j = 0; j &lt; descs2.size(); j++) {
            float dist = jetbot::descriptorDistance(descs1[i], descs2[j]);

            if (dist &lt; best_dist) {
                second_best_dist = best_dist;
                best_dist = dist;
                best_idx = j;
            } else if (dist &lt; second_best_dist) {
                second_best_dist = dist;
            }
        }

        // Lowe's ratio test
        if (best_dist &lt; MATCH_THRESHOLD * second_best_dist) {
            matches.push_back(cv::DMatch(i, best_idx, best_dist));
        }
    }

    std::cout &lt;&lt; "Matches found: " &lt;&lt; matches.size() &lt;&lt; "\n";

    // Draw matches
    cv::Mat match_img;
    cv::drawMatches(img1, convertKeypoints(kps1), 
                    img2, convertKeypoints(kps2), 
                    matches, match_img);

    cv::imwrite("matches.jpg", match_img);
    std::cout &lt;&lt; "✅ Matching complete - result saved to matches.jpg\n";

    // Cleanup
    cudaFree(gpu_img1);
    cudaFree(gpu_img2);

    return 0;
}
</code></pre>

