class CUDAVisionNode : public rclcpp::Node {
private:
    rclcpp::Subscription&lt;sensor_msgs::msg::Image&gt;::SharedPtr image_sub_;
    rclcpp::Publisher&lt;sensor_msgs::msg::Image&gt;::SharedPtr image_pub_;
    jetbot::CUDAProcessor processor_;
    uint8_t *input_gpu_, *output_gpu_;

public:
    CUDAVisionNode() 
        : Node("cuda_vision_node"),
          processor_(0, {1280, 720}) {

        // Subscribe to input topic
        image_sub_ = this-&gt;create_subscription&lt;sensor_msgs::msg::Image&gt;(
            "/camera/image_raw", 10,
            std::bind(&amp;CUDAVisionNode::imageCallback, this, 
                      std::placeholders::_1));

        // Publish processed image
        image_pub_ = this-&gt;create_publisher&lt;sensor_msgs::msg::Image&gt;(
            "/cuda_vision/processed", 10);

        // Allocate GPU memory
        size_t size = 1280 * 720 * 4;
        cudaMalloc(&amp;input_gpu_, size);
        cudaMalloc(&amp;output_gpu_, size);

        RCLCPP_INFO(this-&gt;get_logger(), "CUDA Vision Node initialized");
    }

    ~CUDAVisionNode() {
        cudaFree(input_gpu_);
        cudaFree(output_gpu_);
    }

    void imageCallback(const sensor_msgs::msg::Image::SharedPtr msg) {
        // Convert ROS image to OpenCV
        cv::Mat cv_image = cv_bridge::toCvShare(msg, "rgba8")-&gt;image;

        // Upload to GPU
        cudaMemcpy(input_gpu_, cv_image.data, 
                   cv_image.total() * cv_image.elemSize(),
                   cudaMemcpyHostToDevice);

        // Process
        jetbot::grayscaleConvert(input_gpu_, output_gpu_, 
                                 1280, 720, jetbot::ImageFormat::RGBA);

        // Download result
        uint8_t *host_output = new uint8_t[1280 * 720];
        cudaMemcpy(host_output, output_gpu_, 1280 * 720,
                   cudaMemcpyDeviceToHost);

        // Convert back to ROS image
        cv::Mat result(720, 1280, CV_8UC1, host_output);
        sensor_msgs::msg::Image::SharedPtr output_msg = 
            cv_bridge::CvImage(msg-&gt;header, "mono8", result).toImageMsg();

        image_pub_-&gt;publish(*output_msg);

        delete[] host_output;
    }
};

int main(int argc, char *argv[]) {
    rclcpp::init(argc, argv);
    rclcpp::spin(std::make_shared&lt;CUDAVisionNode&gt;());
    rclcpp::shutdown();
    return 0;
}
