C++<pre><code>// Pre-allocate memory pool
class MemoryPool {
    std::vector&lt;uint8_t*&gt; available;
    std::vector&lt;uint8_t*&gt; in_use;

public:
    uint8_t* acquire(size_t size) {
        if (!available.empty()) {
            auto ptr = available.back();
            available.pop_back();
            in_use.push_back(ptr);
            return ptr;
        }
        uint8_t* ptr;
        cudaMalloc(&amp;ptr, size);
        in_use.push_back(ptr);
        return ptr;
    }

    void release(uint8_t* ptr) {
        available.push_back(ptr);
        // Remove from in_use
    }
};
</code></pre> <p>Impact: Eliminates allocation overhead in loops</p>

