    std::map&lt;std::string, cudaEvent_t&gt; events;

public:
    void startTimer(const std::string&amp; name) {
        cudaEventCreate(&amp;events[name + "_start"]);
        cudaEventCreate(&amp;events[name + "_stop"]);
        cudaEventRecord(events[name + "_start"]);
    }

    void stopTimer(const std::string&amp; name) {
        cudaEventRecord(events[name + "_stop"]);
        cudaEventSynchronize(events[name + "_stop"]);

        float milliseconds = 0;
        cudaEventElapsedTime(&amp;milliseconds, events[name + "_start"],
                            events[name + "_stop"]);

        timings[name].push_back(milliseconds);
    }

    void printStats(const std::string&amp; name) {
        auto&amp; times = timings[name];
        double avg = 0, min = DBL_MAX, max = DBL_MIN;

        for (auto t : times) {
            avg += t;
            min = std::min(min, (double)t);
            max = std::max(max, (double)t);
        }
        avg /= times.size();

        std::cout &lt;&lt; name &lt;&lt; ": avg=" &lt;&lt; avg &lt;&lt; "ms, "
                  &lt;&lt; "min=" &lt;&lt; min &lt;&lt; "ms, max=" &lt;&lt; max &lt;&lt; "ms\n";
