#include &lt;Arduino.h&gt;
#include &lt;RPC.h&gt;

// I2C sensors
#include &lt;Wire.h&gt;

// IMU
const int IMU_ADDR = 0x68;

void setup() {
    Wire.begin();
    RPC.begin();

    // Initialize IMU
    Wire.beginTransmission(IMU_ADDR);
    Wire.write(0x6B);  // PWR_MGMT_1
    Wire.write(0x00);  // Wake up
    Wire.endTransmission();
}

void loop() {
    // Read IMU data at 200 Hz
    static unsigned long last_time = 0;
    if (millis() - last_time &gt;= 5) {  // 200 Hz
        readIMU();
        last_time = millis();
    }
}

void readIMU() {
    // Read accelerometer and gyroscope
    Wire.beginTransmission(IMU_ADDR);
    Wire.write(0x3B);  // ACCEL_XOUT_H
    Wire.endTransmission(false);
    Wire.requestFrom(IMU_ADDR, 14, true);

    int16_t accel_x = Wire.read() &lt;&lt; 8 | Wire.read();
    int16_t accel_y = Wire.read() &lt;&lt; 8 | Wire.read();
    int16_t accel_z = Wire.read() &lt;&lt; 8 | Wire.read();
    int16_t temp = Wire.read() &lt;&lt; 8 | Wire.read();
    int16_t gyro_x = Wire.read() &lt;&lt; 8 | Wire.read();
    int16_t gyro_y = Wire.read() &lt;&lt; 8 | Wire.read();
    int16_t gyro_z = Wire.read() &lt;&lt; 8 | Wire.read();

    // Send to M7 core via RPC
    RPC.call("imu_data", accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
}
