void task_adc_read(void *args) {
    TickType_t xLastWakeTime = osKernelGetTickCount();

    while(1) {
        // Read all ADC channels
        uint16_t adc_values[16];
        for(int i = 0; i &lt; 16; i++) {
            HAL_ADC_Start(&amp;hadc);
            HAL_ADC_PollForConversion(&amp;hadc, 100);
            adc_values[i] = HAL_ADC_GetValue(&amp;hadc);
        }

        // Send to Jetson
        send_adc_data(adc_values);

        // Wait for next period (10ms)
        osDelayUntil(&amp;xLastWakeTime, 10);
    }
