class ObjectDetectionNode : public rclcpp::Node {
public:
    ObjectDetectionNode() : Node("object_detection_node") {
        // Subscribe to camera
        subscription_ = this-&gt;create_subscription&lt;sensor_msgs::msg::Image&gt;(
            "/camera/image_raw",
            10,
            std::bind(&amp;ObjectDetectionNode::image_callback, this, std::placeholders::_1)
        );

        // Publish detections
        publisher_ = this-&gt;create_publisher&lt;vision_msgs::msg::Detection2DArray&gt;(
            "/detections",
            10
        );

        RCLCPP_INFO(this-&gt;get_logger(), "Object detection node started");
    }

private:
    void image_callback(const sensor_msgs::msg::Image::SharedPtr msg) {
        // Process image and detect objects
        auto detections = detect_objects(msg);
        publisher_-&gt;publish(detections);
    }

    vision_msgs::msg::Detection2DArray detect_objects(
        const sensor_msgs::msg::Image::SharedPtr&amp; image
    ) {
        // YOLOv8 inference logic here
        vision_msgs::msg::Detection2DArray detections;
        return detections;
    }

    rclcpp::Subscription&lt;sensor_msgs::msg::Image&gt;::SharedPtr subscription_;
    rclcpp::Publisher&lt;vision_msgs::msg::Detection2DArray&gt;::SharedPtr publisher_;
};

